from pathlib import Path
import csv,json,hashlib
root=Path(__file__).resolve().parents[2]; rows=[]
for r in csv.DictReader((root/'tools/exact_score/exact_scores.tsv').open(),delimiter='\t'):
 rows.append([int(r['player']),int(r['banker'])]+[float(v) for k,v in list(r.items())[2:]])
meta={'version':'BBB_EXACT_SINGLE_SCORE_V1','decks':8,'assumption':'fresh_eight_deck_prior_single_resolved_hand','legal_value_sequences':339400,'merged_depletion_states':6958,'method':'exhaustive_without_replacement_two_hand_marginalization','numeric_tolerance':1e-10,'training_samples':0,'observed_card_ranks':False,'validated_real_world_edge':False}
payload={'meta':meta,'rows':rows}
(root/'exact_score_table.js').write_text('/* Generated by tools/exact_score/build.ps1 and package_table.py. */\n(function(root,factory){const api=factory();if(typeof module==="object"&&module.exports)module.exports=api;if(root)root.BBBExactScoreTable=api;})(typeof window!=="undefined"?window:null,function(){return '+json.dumps(payload,separators=(',',':'))+';});\n',encoding='utf-8',newline='\n')
print('table bytes', (root/'exact_score_table.js').stat().st_size)
